import {Icon, Menu, MenuItem} from '@ui-kitten/components';
import {Action, IACTION, LIST_ACTION} from './helper';
import {KEY_TASK} from '../../../../helper';
import BottomSheetCM from '../../../../../../components/BottomSheet';
import {useState} from 'react';
import TextFieldCM from '../../../../../../components/TextField';
import ButtonCM from '../../../../../../components/Button';
import useBoardStore from '../../../../store';
import {
  useBoardService,
  useUserService,
} from '../../../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';
import {Color} from '../../../../../../../constants';
import {ITask} from '../../../../store/interface';
import ModalFullScreen from '../../../../../../components/ModalFullScreen';
import ModalSelectUser from '../../../../../../components/ModalSelectUser';
import AuthorityAndShareScreen from '../../../../../../components/Authority';
import {useUserStore} from '../../../../../../../zutand/user-store';
import CreateTemplateTask from '../create-template-task';

import RNFS from 'react-native-fs';
import {useTranslation} from 'react-i18next';
import {Platform, Share, View} from 'react-native';
import {getConfig} from '../../../../../../../services/httpClient';
import ReactNativeBlobUtil from 'react-native-blob-util';
type Props = {
  taskSelect?: ITask;
  onClose?: () => void;
  keyTask: KEY_TASK;
};

const ListActionScreen = ({taskSelect, onClose, keyTask}: Props) => {
  const [isVisible, setIsVisible] = useState<Action | null>(null);
  const [valueName, setValueName] = useState(taskSelect?.name);
  const [listTask, setListTask] = useState<ITask>();

  const {t, i18n} = useTranslation();
  const {listHeaderTask, addListHeaderTaskByKey, setListHeaderTask} =
    useBoardStore();
  const {setListGroupUser, setListUser} = useUserStore();
  const UserService = useUserService();
  const BoardServices = useBoardService();
  const handleAction = (action: IACTION) => {
    switch (action.action) {
      case Action.RENAME:
        setIsVisible(Action.RENAME);
        break;
      case Action.DELETE:
        setIsVisible(Action.DELETE);
        break;
      case Action.COPY:
        handleCopyTask();
        break;
      case Action.EXPORT:
        handleExportExcel();
        break;
      case Action.ASSIGN:
        handleAssign();
        break;
      case Action.SAVE_TEMPLATE:
        setIsVisible(Action.SAVE_TEMPLATE);
        break;
      case Action.SHARE_PERMISSIONS:
        setIsVisible(Action.SHARE_PERMISSIONS);
        break;
      default:
        return;
    }
  };

  const handleAssign = async () => {
    setIsVisible(Action.ASSIGN);
    const res = (await BoardServices.getTaskById(
      taskSelect?.id || '',
    )) as ITask;
    const [dataUsers, dataGroups] = await Promise.all([
      UserService.getUser(
        res.assignTaskList.map(v => v.userId),
        {page: 0, size: 10000, role: true},
      ),
      UserService.findListGroup(res.assignGroupList.map(v => v.groupId)),
    ]);
    setListTask(res);
    setListGroupUser(dataGroups);
    setListUser(dataUsers.data);
  };

  const handleChangeName = async () => {
    try {
      const data = await BoardServices.saveListTask(
        {
          ...taskSelect,
          name: valueName,
        },
        'PUT',
      );
      if (data) {
        const newData = listHeaderTask
          .find(header => header.key === keyTask)
          ?.child?.map(task => ({
            ...task,
            name: task.id === taskSelect?.id ? valueName : task.name,
          })) as ITask[];
        addListHeaderTaskByKey(newData, keyTask);
        onClose?.();
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('task.error-change-name'),
        });
      }
    } catch (error) {}
  };

  const handleDelete = async () => {
    try {
      const newData = listHeaderTask
        .find(header => header.key === keyTask)
        ?.child?.filter(task => task.id !== taskSelect?.id) as ITask[];
      onClose?.();
      addListHeaderTaskByKey(newData, keyTask);
      const data = await BoardServices.deleteTaskById(taskSelect?.id);
      if (!data) {
        setListHeaderTask(listHeaderTask);
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {}
  };

  const handleCopyTask = async () => {
    try {
      const prevListHeaderTask = [...listHeaderTask];
      const newData = await BoardServices.copyTaskFormOtherTask(taskSelect?.id);
      if (newData) {
        const prewData = listHeaderTask.find(header => header.key === keyTask)
          ?.child as ITask[];
        addListHeaderTaskByKey([newData, ...prewData], keyTask);
        onClose?.();
        Toast.show({
          type: 'success',
          text1: t('task.clone-success'),
        });
      } else {
        setListHeaderTask(prevListHeaderTask);
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {}
  };
  const handleExportExcel = async () => {
    try {
      const toFile = `${
        Platform.OS === 'android'
          ? RNFS.DownloadDirectoryPath
          : RNFS.DocumentDirectoryPath
      }/${new Date().getTime()}_${taskSelect?.name}`;
      const dataBase64 = await ReactNativeBlobUtil.fetch(
        'GET',
        `${getConfig().BASE_URL}/services/etask/api/export?listTaskId=${
          taskSelect?.id || ''
        }&language=${i18n.language}`,
      )
        .then(res => {
          let status = res.info().status;
          if (status == 200) {
            let base64Str = res.base64();
            return base64Str;
          } else return null;
        })
        .catch(error => {
          console.error('error', error);
          Toast.show({
            type: 'error',
            text1: t('CM.noti'),
            text2: t('CM.error'),
          });
        });
      if (dataBase64) {
        try {
          await RNFS.writeFile(toFile, dataBase64, 'base64');
        } catch (error) {
          console.log(error);
        }
        if (Platform.OS === 'ios') {
          const dataShare = await Share.share({
            url: toFile,
          });
          if (dataShare.action == Share.dismissedAction) {
            Toast.show({
              type: 'error',
              text1: t('CM.noti'),
              text2: t('CM.downloadFail'),
            });
          } else {
            Toast.show({
              type: 'success',
              text1: t('CM.noti'),
              text2: t('CM.downloadSuccess'),
            });
          }
        } else {
          Toast.show({
            type: 'success',
            text1: t('CM.noti'),
            text2: t('CM.downloadSuccess'),
          });
        }
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }

      // Toast.show({
      //   type: 'success',
      //   text1: 'Thông báo',
      //   text2: 'Xuất file excel thành công',
      // });
    } catch (error) {
      console.error('Lỗi trong quá trình xuất file Excel:', error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('task.error-export-excel'),
      });
    }
  };
  return (
    <>
      <Menu>
        {LIST_ACTION.map(action => {
          const template = (
            <MenuItem
              onPress={() => handleAction(action)}
              accessoryLeft={<Icon name={action.icon} />}
              key={action.id}
              title={t(action.name)}
            />
          );
          if (action.action !== Action.SAVE_TEMPLATE) {
            return template;
          } else {
            if (KEY_TASK['my-task'] === keyTask) {
              return template;
            }
            return <View key={action.id}></View>;
          }
        })}
      </Menu>

      <BottomSheetCM
        title="Add"
        withKeyboardAvoidingView
        isVisible={isVisible === Action.RENAME}
        onClose={() => setIsVisible(null)}
        renderContent={
          <>
            <TextFieldCM value={valueName} onChangeText={setValueName} />
            <ButtonCM label={t('CM.save')} onPress={handleChangeName} />
          </>
        }
      />

      <ModalConfirmCM
        isVisible={isVisible === Action.DELETE}
        onClose={() => setIsVisible(null)}
        title={t('HM.titleCancel')}
        content={t('HM.contentCancel')}
        type="cancel"
        labelCancel={t('HM.cancel')}
        labelConfirm={t('CM.labelCancel')}
        styleBtnRight={{backgroundColor: Color.RedE14337}}
        onConfirm={handleDelete}
      />

      {/* <ModalFullScreen
        isVisible={isVisible === Action.ASSIGN}
        children={
          <ModalSelectUser
            onClose={() => setIsVisible(null)}
            type="L"
            assignGroupList={taskSelect?.assignGroupList}
            assignOrgList={taskSelect?.assignOrgList}
            listTask={taskSelect}
          />
        }
      /> */}

      <ModalFullScreen
        isVisible={isVisible === Action.SHARE_PERMISSIONS}
        children={
          <AuthorityAndShareScreen
            type="L"
            onClose={() => setIsVisible(null)}
            resource={taskSelect}
          />
        }
      />

      <ModalFullScreen
        isVisible={isVisible === Action.ASSIGN}
        children={
          listTask ? (
            <ModalSelectUser
              type="L"
              listTask={listTask}
              onClose={() => setIsVisible(null)}
            />
          ) : null
        }
      />

      <ModalFullScreen
        isVisible={isVisible === Action.SAVE_TEMPLATE}
        children={
          <CreateTemplateTask
            onClose={() => setIsVisible(null)}
            taskSelect={taskSelect}
          />
        }
      />
    </>
  );
};

export default ListActionScreen;
