import {Calendar, Divider, Icon} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {Pressable, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {useState} from 'react';
import DatePicker from 'react-native-date-picker';
import {DateUtils} from '../../../../../../../utils';
import styles from './styles';
import {useTranslation} from 'react-i18next';

type Props = {
  onClose: () => void;
  onSave?: (data: any) => void;
  value?: any;
  type: 'startDate' | 'dueDate' | string;
  option?: 'remind' | 'select';
};

const ModalDate = ({
  onClose,
  onSave,
  value,
  type,
  option = 'select',
}: Props) => {
  const {t} = useTranslation();
  const [date, setDate] = useState(value ? new Date(value) : undefined);
  const handleSave = () => {
    const dateSelect = date ? date?.toISOString() : new Date().toISOString();
    onSave?.({
      [type]: dateSelect,
    });
  };

  const handleClear = () => {
    onSave?.({
      [type]: null,
    });
  };
  return (
    <>
      <HeaderCM
        onPressIconLeft={onClose}
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        title={t('board.select-date')}
        renderContentRight={() => (
          <Pressable onPress={handleSave}>
            <TextCM>Done</TextCM>
          </Pressable>
        )}
      />
      <Divider />

      <View style={styles.ctnView}>
        <Icon name="calendar" width={20} height={20} />
        <View>
          <TextCM>
            {date
              ? DateUtils.convertDateToDDMMYYYY_H_M(date)
              : t('task.signDate')}
          </TextCM>
        </View>
      </View>
      <Divider />
      <Calendar
        style={{
          width: '100%',
        }}
        min={option === 'select' ? new Date(1970, 0, 0) : new Date()}
        date={date || new Date()}
        onSelect={nextDate => setDate(nextDate)}
      />

      <View style={styles.ctnTime}>
        <TextCM>Time</TextCM>
        <DatePicker
          date={date || new Date()}
          onDateChange={setDate}
          mode="time"
        />
      </View>

      <Pressable onPress={handleClear}>
        <TextCM style={styles.txtClear}>{t('CM.delete')}</TextCM>
      </Pressable>
    </>
  );
};

export default ModalDate;
