import {
  View,
  ScrollView,
  useWindowDimensions,
  Pressable,
  ActivityIndicator,
} from 'react-native';
import styles from './styles';
import HeaderCM from '../../components/Header/HeaderCM';
import {useTranslation} from 'react-i18next';
import {Color, NavigationName} from '../../../constants';
import Card from './component/Card';
import {useEffect, useState} from 'react';
import {useHomeService} from '../../../hooks/useHomeService';
import {WorkSpace} from '../../../model/interface/home.interface';
import RecentIcon from '../../../assets/images/ic/recent.svg';
import MyWorkSpace from '../../../assets/images/ic/my-workspace.svg';
import ShareWork from '../../../assets/images/ic/shared-worksapce.svg';
import TextCM from '../../components/Text';
import {useNavigation} from '@react-navigation/native';
import {Icon} from '@ui-kitten/components';
import Toast from 'react-native-toast-message';
import ModalInputForm from '../../components/ModalInputForm';

const HomeScreen = () => {
  const {t} = useTranslation();
  const [workplace, setWorkspace] = useState<WorkSpace[]>([]);
  const [ownWork, setOwnWork] = useState<WorkSpace[]>([]);
  const [ownAllWork, setOwnAllWork] = useState<WorkSpace[]>([]);
  const [authorWork, setAuthorWork] = useState<WorkSpace[]>([]);
  const [loading, setLoading] = useState(false);
  const HomeService = useHomeService();
  const cardColors: (keyof typeof Color)[] = ['pending', 'blue', 'blue01'];
  const {width} = useWindowDimensions();
  const navigation = useNavigation<any>();
  const [confirmCreate, setConfirmCreate] = useState(false);
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [errorName, setErrorName] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showAllOwnWork, setShowAllOwnWork] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const [
        workplaceRes,
        ownWorkplaceRes,
        authorWorkplaceRes,
        ownAllWorkplaceRes,
      ] = await Promise.all([
        HomeService.getWorkPlace(),
        HomeService.getOwnWorkPlace(),
        HomeService.getAuthorWorkPlace(),
        HomeService.getAllOwnWorkPlace(),
      ]);
      if (workplaceRes) {
        setWorkspace(workplaceRes.data);
      }
      if (ownWorkplaceRes) {
        setOwnWork(ownWorkplaceRes.data);
      }
      if (ownAllWorkplaceRes) {
        setOwnAllWork(ownAllWorkplaceRes.data);
      }
      if (authorWorkplaceRes) {
        setAuthorWork(authorWorkplaceRes.data);
      }
    } catch (error) {
      console.log('error', error);
    } finally {
      setLoading(false);
    }
  };
  useEffect(() => {
    fetchData();
  }, []);

  const handleDetail = (space: WorkSpace) => {
    navigation.navigate(NavigationName.WorkSpace, {
      spaceId: space.id,
      spaceName: space.name,
    });
  };
  const handleCreateWork = async () => {
    if (!name.trim()) {
      setErrorName(true);
      return;
    }

    setErrorName(false);
    setIsSaving(true); // Bắt đầu loading

    try {
      const payload = {
        name: name.trim(),
        description: description.trim(),
        type: 'default',
      };

      const res = await HomeService.createWorkSpace(payload);

      if (res && res.data) {
        setWorkspace(prev => [res.data, ...prev]);
        setOwnWork(prev => [res.data, ...prev]);

        Toast.show({
          type: 'success',
          text1: t('CM.noti'),
          text2: t('board.create-new-space-success'),
        });

        setConfirmCreate(false);
        setName('');
        setDescription('');
        setErrorName(false);
        setIsSaving(false);
      } else {
        setIsSaving(false);
      }
    } catch (error) {
      setIsSaving(false);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };

  const handleDeleteWorkspace = (id: string) => {
    setWorkspace(prev => prev.filter(item => item.id !== id));

    setOwnWork(prev => prev.filter(item => item.id !== id));
  };
  const handleEditWorkspace = (updated: WorkSpace) => {
    setWorkspace(prev =>
      prev.map(item => (item.id === updated.id ? updated : item)),
    );
    setOwnWork(prev =>
      prev.map(item => (item.id === updated.id ? updated : item)),
    );
  };

  return (
    <>
      <HeaderCM
        title={t('Home')}
        renderContentRight={() => (
          <View
            style={{
              flexDirection: 'row',
              alignItems: 'center',
              columnGap: 8,
            }}>
            <Pressable onPress={() => setConfirmCreate(true)}>
              <Icon fill={'#fff'} width={24} height={24} name="plus-outline" />
            </Pressable>
          </View>
        )}
        showIconBackLeft={false}
      />

      {loading ? (
        <View style={styles.load}>
          <ActivityIndicator size="large" color={Color.BgPrimary} />
        </View>
      ) : (
        <ScrollView>
          <View>
            <View style={styles.topContent}>
              <RecentIcon style={styles.icon} />
              <TextCM style={styles.textHeader}>
                {t('board.current-access')}
              </TextCM>
            </View>
            <ScrollView
              horizontal={true}
              showsHorizontalScrollIndicator={false}
              style={{margin: 10}}>
              <View style={styles.cardGap}>
                {workplace?.length > 0 ? (
                  workplace.map((item, index) => (
                    <Card
                      key={item?.id}
                      data={item}
                      backgroundColor={cardColors[index % cardColors.length]}
                      onPress={() => handleDetail(item)}
                      onDeleteSuccess={handleDeleteWorkspace}
                      onEditSuccess={handleEditWorkspace}
                    />
                  ))
                ) : (
                  <View style={[styles.noSpace, {width}]}>
                    <TextCM style={styles.textHeader}>
                      {t('board.no-space')}
                    </TextCM>
                  </View>
                )}
              </View>
            </ScrollView>
          </View>
          <View>
            <View
              style={[styles.topContent, {justifyContent: 'space-between'}]}>
              <View style={{flexDirection: 'row', alignItems: 'center'}}>
                <MyWorkSpace style={styles.icon} />
                <TextCM style={styles.textHeader}>
                  {t('board.my-workspace')}
                </TextCM>
              </View>
              {ownAllWork.length > 5 && (
                <Pressable onPress={() => setShowAllOwnWork(prev => !prev)}>
                  <TextCM style={{color: '#CA1E66', fontSize: 14}}>
                    {showAllOwnWork ? t('DB.filter.hide') : t('board.view-all')}
                  </TextCM>
                </Pressable>
              )}
            </View>
            <ScrollView
              horizontal={true}
              showsHorizontalScrollIndicator={false}
              style={{margin: 10}}>
              <View style={styles.cardGap}>
                {(showAllOwnWork ? ownAllWork : ownWork).length > 0 ? (
                  (showAllOwnWork ? ownAllWork : ownWork).map((item, index) => (
                    <Card
                      key={item?.id}
                      data={item}
                      backgroundColor={cardColors[index % cardColors.length]}
                      onPress={() => handleDetail(item)}
                      onDeleteSuccess={handleDeleteWorkspace}
                      onEditSuccess={handleEditWorkspace}
                    />
                  ))
                ) : (
                  <View style={[styles.noSpace, {width}]}>
                    <TextCM style={styles.textHeader}>
                      {t('board.no-space')}
                    </TextCM>
                  </View>
                )}
              </View>
            </ScrollView>
          </View>
          <View>
            <View style={styles.topContent}>
              <ShareWork style={styles.icon} />
              <TextCM style={styles.textHeader}>
                {t('board.workspace-permission')}
              </TextCM>
            </View>
            <ScrollView
              horizontal={true}
              showsHorizontalScrollIndicator={false}
              style={{margin: 10}}>
              <View style={styles.cardGap}>
                {authorWork?.length > 0 ? (
                  authorWork.map((item, index) => (
                    <Card
                      key={item?.id}
                      data={item}
                      backgroundColor={cardColors[index % cardColors.length]}
                      onDeleteSuccess={handleDeleteWorkspace}
                      onEditSuccess={handleEditWorkspace}
                    />
                  ))
                ) : (
                  <View style={[styles.noSpace, {width}]}>
                    <TextCM style={styles.textHeader}>
                      {t('board.no-space')}
                    </TextCM>
                  </View>
                )}
              </View>
            </ScrollView>
          </View>
        </ScrollView>
      )}

      <ModalInputForm
        visible={confirmCreate}
        onClose={() => {
          setConfirmCreate(false);
          setName('');
          setDescription('');
          setErrorName(false);
        }}
        title={t('board.add-new-word-space')}
        fields={[
          {
            label: t('board.space-name'),
            placeholder: t('board.space-name-placeholder'),
            value: name,
            onChange: text => {
              setName(text);
              setErrorName(!text.trim());
            },
            required: true,
          },
          {
            label: t('board.introduce'),
            placeholder: t('NT.board.placeholderDescription'),
            value: description,
            onChange: setDescription,
            multiline: true,
            maxLength: 225,
          },
        ]}
        onSubmit={handleCreateWork}
        isSubmitting={isSaving}
        submitLabel={t('CM.save')}
        cancelLabel={t('CM.labelCancel')}
      />
    </>
  );
};

export default HomeScreen;
