import {ScrollView, TextInput, TouchableOpacity, View} from 'react-native';
import TextCM from '../../../../../../components/Text';
import {Divider} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import {useBoardService} from '../../../../../../../hooks/apiHooks/useAPI';
import {useEffect, useState} from 'react';
import {DateUtils} from '../../../../../../../utils';
import {useTranslation} from 'react-i18next';
import Toast from 'react-native-toast-message';
import SearchIcon from '../../../../../../../assets/images/ic/search.svg';
import CalenderIcon from '../../../../../../../assets/images/ic/calendar-date.svg';
import DatePickerModal from '../../../../../../components/ModalPickCalender';
import styles from './styles';
import FormCard from './FormCard';
import GroupButtonCM from '../../../../../../components/GroupButton';
type Props = {
  onClose: () => void;
  handleSubmitData: (data: any) => void;
  selectedFormId?: string;
};

interface FormItem {
  formName: string;
  formCode: string;
  createdDate?: string;
  createdBy: string;
  formId: string;
}

const FormAttach = ({onClose, handleSubmitData, selectedFormId}: Props) => {
  const [listForm, setListForm] = useState<FormItem[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedIndex, setSelectedIndex] = useState<string | null>(null);

  const [searchText, setSearchText] = useState('');
  const [createdDate, setCreatedDate] = useState<string | null>(null);
  const [showDatePicker, setShowDatePicker] = useState(false);
  const BoardServices = useBoardService();
  const {t} = useTranslation();

  const formatted = createdDate
    ? DateUtils.convertDateToYYYYMMDD1(createdDate)
    : '_';

  const getDataForm = async () => {
    try {
      setIsLoading(true);

      const body = {
        createdDate: createdDate ? formatted : null,
        textSearch: searchText,
      };
      const data = await BoardServices.getListFormEflow(body);
      if (data && data?.content) {
        setListForm(data?.content);
        if (selectedFormId) {
          const foundIndex = data.content.find(
            (form: {formId: string}) => form.formId === selectedFormId,
          );
          if (foundIndex) {
            setSelectedIndex(foundIndex.formId);
          }
        }
      } else {
        setListForm([]);
      }
    } catch (error) {
      console.log('Error fetching data:', error);
      setListForm([]);
    } finally {
      setIsLoading(false);
    }
  };
  const onSubmit = () => {
    const selectForm = listForm.find(form => form.formId === selectedIndex);
    if (selectForm) {
      handleSubmitData(selectForm);
      onClose?.();
      Toast.show({
        type: 'success',
        text1: t('CM.noti'),
        text2: t('task.add-formtask-success'),
      });
    }
  };
  useEffect(() => {
    getDataForm();
  }, [searchText, createdDate]);

  return (
    <View style={{flex: 1}}>
      <HeaderCM
        style={{backgroundColor: '#fff'}}
        contentStyle={{backgroundColor: '#fff'}}
        titleStyle={{color: '#000810'}}
        fillIconBackLeft="#000810"
        onPressIconLeft={() => onClose?.()}
        title={t('task.formtask-title')}
        alignment="start"
      />
      <Divider />
      <View style={styles.headerCtn}>
        <View style={styles.inputCtn}>
          <SearchIcon width={20} height={20} />
          <TextInput
            style={styles.input}
            placeholder={t('task.formtask-placeholder')}
            value={searchText}
            onChangeText={setSearchText}
            onSubmitEditing={() => getDataForm()}
          />
        </View>
        <TouchableOpacity
          style={styles.pickDay}
          onPress={() => setShowDatePicker(true)}>
          <TextCM>{t('task.created-date')}</TextCM>
          {createdDate ? (
            <TextCM>{DateUtils.convertDateToDDMMYYYY(createdDate)}</TextCM>
          ) : (
            <CalenderIcon width={20} height={20} />
          )}
        </TouchableOpacity>
      </View>

      <ScrollView
        contentContainerStyle={
          isLoading || listForm.length === 0
            ? {flexGrow: 1, justifyContent: 'center', alignItems: 'center'}
            : {}
        }>
        {isLoading ? (
          <TextCM style={{padding: 16}}>{t('task.loading')}</TextCM>
        ) : listForm.length === 0 ? (
          <TextCM>{t('task.noDataDisplay')}</TextCM>
        ) : (
          <View style={{padding: 16, gap: 12}}>
            {listForm.map((list, index) => (
              <FormCard
                key={list.formId}
                order={index + 1}
                formName={list.formName}
                formCode={list.formCode}
                createdDate={
                  list.createdDate
                    ? DateUtils.convertDateToDDMMYYYY(list.createdDate)
                    : '_'
                }
                createdBy={list.createdBy}
                selected={selectedIndex === list.formId}
                onSelect={() => setSelectedIndex(list.formId)}
              />
            ))}
          </View>
        )}
      </ScrollView>
      <View
        style={{
          marginBottom: 12,
        }}>
        <GroupButtonCM
          containerStyle={styles.groupBtn}
          labelLeft={t('CM.labelCancel')}
          labelRight={t('CM.confirm')}
          onPressLeft={() => onClose?.()}
          onPressRight={onSubmit}
        />
      </View>
      <DatePickerModal
        visible={showDatePicker}
        onClose={() => setShowDatePicker(false)}
        onSelect={date => {
          setCreatedDate(date);
        }}
      />
    </View>
  );
};

export default FormAttach;
