// FormCard.tsx
import React from 'react';
import { View, StyleSheet } from 'react-native';
import TextCM from '../../../../../../components/Text';
import { useTranslation } from 'react-i18next';
import { Radio } from '@ui-kitten/components';
import styles from './styles';

type Props = {
  order: number;
  formName: string;
  formCode: string;
  createdDate: string;
  createdBy: string;
  selected: boolean;
  onSelect: () => void;
};

const FormCard: React.FC<Props> = ({
  order,
  formName,
  formCode,
  createdDate,
  createdBy,
  selected,
  onSelect,
}) => {
    const {t} = useTranslation();
  
  return (
    <View style={styles.card}>
      <View style={styles.headerRow}>
        <Radio checked={selected} onChange={onSelect}  />
        <TextCM style={styles.orderText}>#{order}</TextCM>
      </View>

      <View style={styles.row}>
        <TextCM style={styles.label}>{t('HM.board.table-formName')}: </TextCM>
        <TextCM style={styles.value}>{formName}</TextCM>
      </View>

      <View style={styles.row}>
        <TextCM style={styles.label}>{t('HM.board.table-formCode')}:</TextCM>
        <TextCM style={styles.value}>{formCode}</TextCM>
      </View>

      <View style={styles.row}>
        <TextCM style={styles.label}>{t('HM.board.table-created-date')}:</TextCM>
        <TextCM style={styles.value}>{createdDate}</TextCM>
      </View>

      <View style={styles.row}>
        <TextCM style={styles.label}>{t('HM.board.table-created-by')}:</TextCM>
        <TextCM style={styles.value}>{createdBy}</TextCM>
      </View>
    </View>
  );
};

export default FormCard;


