import {useTranslation} from 'react-i18next';
import HeaderCM from '../../../components/Header/HeaderCM';
import {Icon, Menu, MenuItem, TopNavigationAction} from '@ui-kitten/components';
import {useState} from 'react';
import BottomSheetCM from '../../../components/BottomSheet';
import TextCM from '../../../components/Text';
type Props = {
  selectTab: 'mine' | 'org';
  setSelectTab: (tab: 'mine' | 'org') => void;
};
const HeaderReport = ({selectTab, setSelectTab}: Props) => {
  const {t} = useTranslation();
  const [menuVisible, setMenuVisible] = useState(false);
  const renderMenuAction = (): React.ReactElement => (
    <TopNavigationAction
      icon={<Icon fill={'#fff'} name="funnel-outline" />}
      onPress={() => setMenuVisible(true)}
    />
  );
  const changeSelectTab = async (tab: 'mine' | 'org') => {
    if (tab !== selectTab) {
      setSelectTab(tab);
      setMenuVisible(false);
    }
  };
  const renderAction = () => {
    return (
      <Menu>
        <MenuItem
          key={'org'}
          title={props => <TextCM {...props}>{t('board.organization')}</TextCM>}
          onPress={() => changeSelectTab('org')}
          accessoryRight={
            selectTab == 'org' ? <Icon name="checkmark" /> : undefined
          }
        />
        <MenuItem
          key={'mine'}
          title={props => <TextCM {...props}>{t('board.mine')}</TextCM>}
          onPress={() => changeSelectTab('mine')}
          accessoryRight={
            selectTab == 'mine' ? <Icon name="checkmark" /> : undefined
          }
        />
      </Menu>
    );
  };
  return (
    <>
      <HeaderCM
        title={t('board.statistical')}
        renderContentRight={renderMenuAction}
      />
      <BottomSheetCM
        title={t('task.classify')}
        onClose={() => setMenuVisible(false)}
        isVisible={menuVisible}
        renderContent={renderAction()}
      />
    </>
  );
};

export default HeaderReport;
