import {Pressable, View} from 'react-native';
import TextCM from '../../../../components/Text';
import {ITaskDetail} from '../task-detail-item/helper';
import {DateUtils} from '../../../../../utils';
import {Icon} from '@ui-kitten/components';
import styles from './styles';
import {
  IconFilePresent,
  IconMessageChat,
  IconSubTask,
} from '../../../../../assets/images';
import {ProgressBar} from 'react-native-paper';
import {PRIORITIES} from '../../../board/components/create-new-task/helper';
import {useState} from 'react';
import ModalFullScreen from '../../../../components/ModalFullScreen';
import ModalSelectUser from '../../../../components/ModalSelectUser';
import RenderListUserAssign from './list-assign';
import BottomSheetCM from '../../../../components/BottomSheet';
import ListActionTaskDetail from '../ListActionTaskDetail';
import {useTranslation} from 'react-i18next';

type Props = {
  itemTask: ITaskDetail;
  listTask: ITaskDetail[];
  setListTask: (state: ITaskDetail[]) => void;
};

const ItemTicket = ({itemTask, listTask, setListTask}: Props) => {
  const {t} = useTranslation();
  const [showModalUser, setShowModalUser] = useState(false);
  const [isShowAction, setIsShowAction] = useState(false);

  const toggleShowModalUser = () => setShowModalUser(!showModalUser);

  const renderListUserAssign = () => {
    return (
      <Pressable onPress={toggleShowModalUser}>
        <RenderListUserAssign
          assignTaskList={itemTask.assignTaskList}
          assignGroupList={itemTask.assignGroupList}
          assignOrgList={itemTask.assignOrgList}
        />
      </Pressable>
    );
  };

  const getPriority = () => {
    return PRIORITIES.find(item => item.value === itemTask.priority)?.icon;
  };

  return (
    <View style={styles.container}>
      <View style={styles.ctnName}>
        <TextCM style={styles.taskName}>{itemTask.name}</TextCM>
        {itemTask.priority && getPriority()}
      </View>

      {itemTask.createdDate && (
        <TextCM style={styles.txtItem}>
          {t('CM.createDateCard')}:{' '}
          {DateUtils.convertDateToDDMMYYYY_H_M(itemTask.createdDate)}
        </TextCM>
      )}

      {itemTask.startDate && (
        <TextCM style={styles.txtItem}>
          {t('task.start-date')}:{' '}
          {DateUtils.convertDateToDDMMYYYY_H_M(itemTask.startDate)}
        </TextCM>
      )}

      {itemTask.dueDate && (
        <TextCM style={styles.txtItem}>
          {t('task.due-date')}:{' '}
          {DateUtils.convertDateToDDMMYYYY_H_M(itemTask.dueDate)}
        </TextCM>
      )}

      {itemTask.numberSubtasks > 0 && (
        <View style={styles.ctnBumberTask}>
          <ProgressBar
            style={styles.ctnProgressbar}
            progress={itemTask.percent}
            color={'rgb(202, 30, 102)'}
          />
          <TextCM>{`${Number(itemTask.percent * 100).toFixed(1)}% (${Math.ceil(
            itemTask.percent * itemTask.numberSubtasks,
          )}/${itemTask.numberSubtasks})`}</TextCM>
        </View>
      )}

      {itemTask.tags && itemTask.tags.length > 0 && (
        <View style={styles.ctnTag}>
          {itemTask.tags.map((item: string, index: number) => {
            return (
              <View key={index} style={styles.ctnItemTag}>
                <TextCM numberOfLines={1} style={styles.txtTag}>
                  {item}
                </TextCM>
              </View>
            );
          })}
        </View>
      )}

      <View style={styles.ctnUserList}>
        {itemTask.assignTaskList.length == 0 &&
        itemTask.assignGroupList.length == 0 &&
        itemTask.assignOrgList.length == 0 ? (
          <Pressable onPress={toggleShowModalUser} style={styles.addItem}>
            <Icon name="person-add" width={16} height={16} />
          </Pressable>
        ) : (
          renderListUserAssign()
        )}

        <View style={styles.ctnTask}>
          <IconFilePresent width={16} height={16} />
          <TextCM style={[styles.ctnText, {color: '#9333EA'}]}>
            {itemTask.numberAttachments}
          </TextCM>
        </View>
        <View style={styles.ctnTask}>
          <IconMessageChat width={16} height={16} />
          <TextCM style={[styles.ctnText, {color: '#F59E0B'}]}>
            {itemTask.numberComments}
          </TextCM>
        </View>
        <View style={styles.ctnTask}>
          <IconSubTask width={16} height={16} />
          <TextCM style={[styles.ctnText, {color: '#DB2777'}]}>
            {itemTask.numberSubtasks}
          </TextCM>
        </View>
        <View style={{flex: 1}}></View>
        <Pressable onPress={() => setIsShowAction(true)}>
          <Icon name="more-horizontal" width={24} height={24} />
        </Pressable>
      </View>

      {/* <Divider />

      <Pressable style={styles.ctnAddSubTask}>
        <Icon fill={Color.Text} name="plus-circle" width={20} height={20} />
        <TextCM style={styles.txtAddSubTask}>Thêm công việc con</TextCM>
      </Pressable> */}

      <ModalFullScreen
        isVisible={showModalUser}
        children={
          <ModalSelectUser
            task={itemTask}
            type="T"
            onClose={toggleShowModalUser}
          />
        }
      />
      <BottomSheetCM
        title={'Action'}
        isVisible={isShowAction}
        onClose={() => setIsShowAction(false)}
        renderContent={
          <ListActionTaskDetail
            taskSelect={itemTask}
            onClose={() => setIsShowAction(false)}
            listTask={listTask}
            setListTask={setListTask}
          />
        }
      />
    </View>
  );
};

export default ItemTicket;
