import {Divider} from '@ui-kitten/components';
import HeaderCM from '../../../../../../components/Header/HeaderCM';
import TextCM from '../../../../../../components/Text';
import {Keyboard, Platform, Pressable} from 'react-native';
import {useRef, useState} from 'react';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import {actions, RichEditor, RichToolbar} from 'react-native-pell-rich-editor';
import {
  handleBullet,
  handleHead,
  handleHeadH2,
  handleHeadH3,
  handleLink,
  handleOrder,
  handleRedo,
  handleSetBold,
  handleSetItalic,
  handleSetUnderline,
  handleUndo,
} from './helper';

type Props = {
  onClose: () => void;
  onSave?: (data: any) => void;
  value?: string;
};

const ModalDescription = ({onClose, onSave, value}: Props) => {
  const [valueText, setValueText] = useState<string | undefined>(value);
  const richText = useRef(null);
  const handleSave = () => {
    onSave?.({
      description: valueText,
    });
    Keyboard.dismiss();
  };
  return (
    <>
      <HeaderCM
        onPressIconLeft={onClose}
        style={{
          backgroundColor: '#fff',
        }}
        contentStyle={{
          backgroundColor: '#fff',
        }}
        titleStyle={{
          color: '#000810',
        }}
        fillIconBackLeft="#000810"
        title="Description"
        renderContentRight={() => (
          <Pressable onPress={handleSave}>
            <TextCM>Done</TextCM>
          </Pressable>
        )}
      />
      <Divider />
      <KeyboardAwareScrollView>
        <RichToolbar
          editor={richText}
          actions={[
            actions.setBold,
            actions.setItalic,
            actions.setUnderline,
            actions.insertBulletsList,
            actions.insertOrderedList,
            actions.heading1,
            actions.heading2,
            actions.heading3,
            actions.insertLink,
            actions.undo,
            actions.redo,
          ]}
          iconMap={
            Platform.OS === 'ios'
              ? {
                  [actions.setBold]: handleSetBold,
                  [actions.setItalic]: handleSetItalic,
                  [actions.setUnderline]: handleSetUnderline,
                  [actions.insertBulletsList]: handleBullet,
                  [actions.insertOrderedList]: handleOrder,
                  [actions.heading1]: handleHead,
                  [actions.heading2]: handleHeadH2,
                  [actions.heading3]: handleHeadH3,
                  [actions.insertLink]: handleLink,
                  [actions.undo]: handleUndo,
                  [actions.redo]: handleRedo,
                }
              : {
                  [actions.heading1]: handleHead,
                  [actions.heading2]: handleHeadH2,
                  [actions.heading3]: handleHeadH3,
                }
          }
        />

        <RichEditor
          editorStyle={{
            contentCSSText: `contentCSSText: font-family: Inter`,
          }}
          ref={richText}
          initialContentHTML={valueText}
          onChange={setValueText}
        />
      </KeyboardAwareScrollView>
    </>
  );
};

export default ModalDescription;
