import {FlatList} from 'react-native';

import {styles} from './styles';
import {TaskGroup} from '../../../../model/interface/dashboard.interface';
import TableTaskCard from './TableTaskCard';

type Props = {
  listTask?: TaskGroup[];
  type?: string | null;
};
export default function DashboardTaskList({listTask, type}: Props) {
  return (
    <FlatList
      style={styles.container}
      data={listTask}
      renderItem={({item, index}) => (
        <TableTaskCard item={item} key={item.listTaskId} type={type} index={index} listTask={listTask} />
      )}
    />
  );
}
