import {
  CheckBox,
  Icon,
  IndexPath,
  Input,
  Layout,
  List,
  MenuItem,
  OverflowMenu,
  Popover,
  Select,
  SelectItem,
} from '@ui-kitten/components';
import {
  Image,
  Keyboard,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  TouchableOpacity,
  View,
} from 'react-native';
import styles from './styles';
import TextCM from '../../../../../../components/Text';
import {Color, String} from '../../../../../../../constants';
import {useEffect, useRef, useState} from 'react';
import InputCM from '../../../../../../components/TextField/InputCM';
import ModalInputForm from '../../../../../../components/ModalInputForm';
import {useTranslation} from 'react-i18next';
import {ListDropdownField} from './helper';
import {
  useBoardService,
  useUserService,
} from '../../../../../../../hooks/apiHooks/useAPI';
import {ICustomField, IFieldValue} from '../../../../helper';
import EditIcon from '../../../../../../../assets/images/ic//edit-black.svg';
import DatePickerModal from '../../../../../../components/ModalPickCalender';
import {DateUtils} from '../../../../../../../utils';
import {IUser} from '../../../../../../../model/interface/account.interface';
import InputRichText, {
  InputRichTextRef,
} from '../../../../../../components/InputRichToolBar';
import ModalSignature from '../../../../../../components/Signature';
import DeleteIcon from '../../../../../../../assets/images/ic/delete-listtask.svg';
import ModalConfirmCM from '../../../../../../components/ModalConfirm';

type Props = {
  taskId?: string;
};
const CustomField = ({taskId}: Props) => {
  const inputRef = useRef<Input | null>(null);

  const [visible, setVisible] = useState(false);
  const [textInput, setTextInput] = useState<string>('');
  const [listCustom, setListCustom] = useState<ICustomField[]>([]);
  const [confirmEdit, setConfirmEdit] = useState(false);
  const [name, setName] = useState('');
  const [value, setValue] = useState('');

  const [listUser, setListUser] = useState<IUser[]>([]);
  const [totalItem, setTotalItem] = useState(0);
  const [refreshing, setRefreshing] = useState(false);
  const [page, setPage] = useState(0);
  const [valuesAss, setValuesAss] = useState<{[key: string]: string}>({});
  const [showList, setShowList] = useState<string | null>(null);
  const [openSignature, setOpenSignature] = useState<string | null>(null);
  const [checked, setChecked] = useState<{[key: string]: boolean}>({});
  const [images, setImages] = useState<Record<string, string>>({});
  const [currency, setCurrency] = useState('');
  const [listValue, setListValue] = useState<string[]>(['']);
  const [confirmDeleteVisible, setConfirmDeleteVisible] = useState<
    string | null
  >(null);
  const editorRefs = useRef<Record<string, InputRichTextRef>>({});
  const [description, setDescription] = useState('');
  const [typeValue, setTypeValue] = useState<string>('');
  const [showDatePicker, setShowDatePicker] = useState<string | null>(null);
  const [selectedDate, setSelectedDate] = useState<{
    [key: string]: Date | null;
  }>({});
  const [selectedIndexes, setSelectedIndexes] = useState<
    Record<string, IndexPath | null>
  >({});
  const [signatureData, setSignatureData] = useState<
    Record<string, string | null>
  >({});
  const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  const checkPhone = /^\+?[0-9]{8,12}$/;
  const [modalEditForm, setModalEditForm] = useState<string | null>(null);
  const {t} = useTranslation();

  const BoardService = useBoardService();
  const UserServices = useUserService();
  const onRefresh = () => {
    setRefreshing(true);
    setPage(0);
    getUser(0);
  };

  const fetchNextData = () => {
    if (listUser?.length < totalItem) {
      setPage(page + 1);
      getUser(page + 1);
    }
  };
  const getCustomField = async () => {
    try {
      if (!taskId) return;
      const data = await BoardService.getCustomFieldById(taskId);

      if (Array.isArray(data)) {
        setListCustom(data);
      } else {
        setListCustom([]);
      }
    } catch (error) {
      console.log('error', error);
      setListCustom([]);
    }
  };

  const getUser = async (page: number) => {
    try {
      const body = {
        q: '',
      };
      const params = {
        page: page,
        size: 50,
        role: true,
      };
      const data = await UserServices.getUser(body, params);
      if (data) {
        if (page === 0) {
          setListUser(data.data);
        } else {
          setListUser([...listUser, ...data.data]);
        }
        setTotalItem(data.total);
      }
    } catch (error) {
    } finally {
      setRefreshing(false);
    }
  };
  const handleSelect = (id: string, value: string) => {
    setValuesAss(prev => ({...prev, [id]: value}));
    setShowList(null);
  };
  const getGuild = () => {
    let result = '';
    for (let j = 0; j < 19; j++) {
      const i = Math.floor(Math.random() * 16).toString(16);
      result += i;
    }
    return result;
  };
  const updateCFapi = async (
    listId: string,
    newValue?: string | boolean,
    type?: string,
    name?: string,
    description?: string,
    listValue?: string[],
    currency?: string,
  ) => {
    try {
      const updateItem = listCustom?.find(item => item.id === listId);
      if (updateItem) {
        const bodyUpdate = {
          ...updateItem,
          fieldValue: updateItem.fieldValue.map(fv => {
            return {
              ...fv,
              value: newValue,
              name: name,
              description: description,
              type: type,
              listValue: listValue,
              currency: currency,
            };
          }),
        };
        if (bodyUpdate) {
          const data = await BoardService.updateCustomField(bodyUpdate);
          setListCustom(prev =>
            prev.map(item => (item.id === listId ? data : item)),
          );
        }
      }
    } catch (error) {
      console.log('cap nhat that bai');
    }
  };
  const addCustomField = async (
    name: string,
    description: string,
    type: string,
    currency: null | string,
    listValue?: string[],
  ) => {
    const body = {
      status: 'true',
      taskId: taskId,
      fieldValue: [
        {
          id: getGuild(),
          name: name,
          description: description,
          type: type,
          currency: currency,

          ...(listValue ? {listValue: listValue} : {}),
        },
      ],
    };
    try {
      const res = await BoardService.addCustomField(body);
      if (res) {
        setListCustom(prev => [...prev, res]);
      }
    } catch (error) {
      console.log('error', error);
    }
  };
  const updateFieldValue = (
    fieldId: string,
    taskId: string,
    newValue: string,
    name?: string,
    description?: string,
    type?: string,
    listValue?: string[],
  ) => {
    setListCustom?.(
      prev =>
        prev?.map(task => {
          if (task.id === taskId) {
            return {
              ...task,
              fieldValue: task.fieldValue.map(f =>
                f.id === fieldId ? {...f, value: newValue} : f,
              ),
            };
          }
          return task;
        }) || null,
    );
  };
  const handleConfirmDelete = async (id: string) => {
    try {
      await BoardService.deleteCustomField(id);
      if (listCustom) {
        const newList = listCustom.filter(item => item.id !== id);
        setListCustom(newList);
      }
      setConfirmDeleteVisible(null);
    } catch (error) {
      console.log('error', error);
    }
  };
  useEffect(() => {
    getCustomField();
    getUser(0);
  }, []);
  useEffect(() => {
    if (listCustom && listCustom.length > 0) {
      getImage();
    }
  }, [listCustom]);
  const getImage = async () => {
    try {
      if (!listCustom) return;

      const results = await Promise.all(
        listCustom?.flatMap(
          list =>
            list.documents?.map(async doc => {
              const base64 = await BoardService.getImageCustomFieldById(
                list.id,
                doc.resourceId,
              );
              return {id: doc.id, base64};
            }) ?? [],
        ),
      );

      const map: Record<string, string> = {};
      results.forEach(item => {
        if (item) map[item.id] = item.base64;
      });

      setImages(map);
    } catch (error) {
      console.log('error', error);
    }
  };
  const uploadImage = async (
    taskHdrId: string,
    fieldId: string,
    sig: string | null,
  ) => {
    try {
      const doc = listCustom
        ?.find(list => list.id === taskHdrId)
        ?.documents?.find(d => d.resourceId === fieldId);

      if (!doc) {
        console.log('Không tìm thấy document');
        return;
      }
      if (!sig) {
        console.log('Không có chữ ký để upload');
        return;
      }
      const body = {
        taskHdrId,
        base64: sig,
        contentType: 'image/png',
        fileName: `signature_${doc.resourceId}`,
        fieldId: doc.resourceId,
      };
      const formData = new FormData();
      formData.append('dto', JSON.stringify(body));
      formData.append('file', 'null');
      const db = await BoardService.uploadImage(formData);
    } catch (error) {
      console.log('error', error);
    }
  };
  const renderAssigneeInput = (
    fv: IFieldValue,
    inputRef: any,
    valuesAss: any,
  ) => {
    return (
      <Input
        placeholder="Chọn người"
        ref={inputRef}
        value={valuesAss[fv.id] || fv.value}
        showSoftInputOnFocus={false}
        onFocus={() => setShowList(fv.id)}
        style={styles.choosePerson}
        selection={{start: 0, end: 0}}
        autoCorrect={false}
      />
    );
  };

  const handleReset = () => {
    setName('');
    setDescription('');
    setListValue([]);
    setCurrency('');
  };
  return (
    <View>
      <View style={styles.ctnTaskDate}>
        <Icon name="funnel-outline" width={20} height={20} />
        <View style={styles.ctnSubTask}>
          <TextCM style={styles.ctnTextItem}>{t('task.customfield')}</TextCM>
        </View>
        <OverflowMenu
          style={{width: 200}}
          anchor={() => (
            <Pressable onPress={() => setVisible(true)}>
              <TextCM style={{color: Color.primary01}}>
                {t('task.add-customfield')}
              </TextCM>
            </Pressable>
          )}
          visible={visible}
          placement="top"
          onBackdropPress={() => setVisible(false)}>
          <MenuItem
            disabled
            title={() => (
              <View style={styles.menuItemSearch}>
                <InputCM
                  placeholder={t('task.search-type-customfield')}
                  value={textInput}
                  onChangeText={setTextInput}
                  style={styles.searchType}
                  autoFocus={true}
                />
              </View>
            )}
          />
          <>
            {ListDropdownField.filter(item =>
              item.key.toLowerCase().includes(textInput.toLowerCase()),
            ).map(item => {
              return (
                <MenuItem
                  key={item.key}
                  title={() => (
                    <View style={styles.menuItem}>
                      {item.icon}
                      <TextCM style={styles.text}> {item.value}</TextCM>
                    </View>
                  )}
                  onPress={() => {
                    setVisible(false);
                    setConfirmEdit(true);
                    setTypeValue(item.key);
                  }}
                />
              );
            })}
          </>
        </OverflowMenu>

        <ModalInputForm
          visible={confirmEdit}
          onClose={() => {
            setConfirmEdit(false);
            handleReset();
          }}
          title={t('task.setup-customfield')}
          data={ListDropdownField}
          fields={[
            {
              label: t('task.name-field'),
              placeholder: t('task.enter-name-field'),
              value: name,
              onChange: (text: any) => setName(text),
              required: true,
            },
            {
              label: t('task.description'),
              placeholder: t('task.enter-description'),
              value: description,
              onChange: setDescription,
              multiline: true,
              maxLength: 225,
            },
            {
              label: t('task.type-field'),
              placeholder: t('task.enter-type-field'),
              value: typeValue,
              onChange: setTypeValue,
              type: 'select',
            },
            ...(typeValue === 'currency'
              ? [
                  {
                    label: t('task.currency'),
                    placeholder: t('task.enter-currency'),
                    value: currency,
                    onChange: (text: any) => setCurrency(text),
                  },
                ]
              : []),
            ...(typeValue === 'select'
              ? [
                  {
                    label: t('task.list-value'),
                    placeholder: t('task.enter-list-value'),
                    value: listValue,
                    onChange: setListValue,
                    type: 'listSelect',
                  },
                ]
              : []),
          ]}
          onSubmit={() => {
            addCustomField(name, description, typeValue, currency, listValue);
            setConfirmEdit(false);
            handleReset();
          }}
          submitLabel={t('CM.save')}
          cancelLabel={t('CM.labelCancel')}
        />
      </View>
      <View style={{flexDirection: 'column'}}>
        {listCustom ? (
          listCustom.map((item, index) => (
            <View>
              {item.fieldValue.map(fv => (
                <View key={fv.id}>
                  {ListDropdownField.map(list => {
                    if (list.key === fv.type) {
                      return (
                        <View key={list.key} style={styles.tableCtn}>
                          <Pressable
                            onPress={() => {
                              Keyboard.dismiss();
                              editorRefs.current[fv.id]?.blur();
                            }}
                            style={{
                              alignItems: 'center',
                              justifyContent: 'center',
                            }}>
                            <View style={styles.leftCtn}>
                              <View style={styles.leftTab}>
                                <View style={{marginRight: 12}}>
                                  {list.icon}
                                </View>
                                <TextCM>{fv.name}</TextCM>
                              </View>
                              <Pressable
                                onPress={() => {
                                  setModalEditForm(item.id);
                                  setName(fv.name);
                                  setDescription(fv.description);
                                  setTypeValue(fv.type);
                                  setCurrency(fv.currency);
                                  setValue(fv.value);
                                  setListValue(fv.listValue);
                                }}>
                                <EditIcon style={styles.icon} />
                              </Pressable>
                              <ModalInputForm
                                visible={modalEditForm === item.id}
                                onClose={() => {
                                  setModalEditForm(null);
                                  handleReset();
                                }}
                                title={t('task.setup-customfield')}
                                data={ListDropdownField}
                                fields={[
                                  {
                                    label: t('task.name-field'),
                                    placeholder: t('task.enter-name-field'),
                                    value: name,
                                    onChange: (text: any) => setName(text),
                                    required: true,
                                  },
                                  {
                                    label: t('task.description'),
                                    placeholder: t('task.enter-description'),
                                    value: description,
                                    onChange: setDescription,
                                    multiline: true,
                                    maxLength: 225,
                                  },
                                  {
                                    label: t('task.type-field'),
                                    placeholder: t('task.enter-type-field'),
                                    value: typeValue,
                                    onChange: setTypeValue,
                                    type: 'select',
                                  },
                                  ...(typeValue === 'currency'
                                    ? [
                                        {
                                          label: t('task.currency'),
                                          placeholder: t('task.enter-currency'),
                                          value: currency,
                                          onChange: (text: any) =>
                                            setCurrency(text),
                                        },
                                      ]
                                    : []),
                                  ...(typeValue === 'select'
                                    ? [
                                        {
                                          label: t('task.list-value'),
                                          placeholder: t(
                                            'task.enter-list-value',
                                          ),
                                          value: listValue,
                                          onChange: setListValue,
                                          type: 'listSelect',
                                        },
                                      ]
                                    : []),
                                ]}
                                onSubmit={() => {
                                  updateCFapi(
                                    item.id,
                                    value,
                                    typeValue,
                                    name,
                                    description,
                                    listValue,
                                    currency,
                                  );
                                  setModalEditForm(null);
                                  handleReset();
                                }}
                                submitLabel={t('CM.save')}
                                cancelLabel={t('CM.labelCancel')}
                              />
                            </View>
                          </Pressable>
                          <View style={styles.rightFCtn}>
                            {fv.type === 'text' && (
                              <View style={styles.rightCtn}>
                                <Input
                                  value={fv.value}
                                  onChangeText={newText => {
                                    updateFieldValue(fv.id, item.id, newText);
                                  }}
                                  multiline={true}
                                  autoCorrect={false}
                                  onBlur={() => {
                                    updateCFapi(
                                      item.id,
                                      fv.value,
                                      fv.type,
                                      fv.name,
                                      fv.description,
                                      fv.listValue,
                                    );
                                  }}
                                  style={styles.inputCtn}
                                />
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'textarea' && (
                              <View style={styles.rightCtn}>
                                <View
                                  style={{flex: 1, height: 100}}
                                  >
                                
                                    <InputRichText
                                      ref={ref => {
                                        if (ref) {
                                          editorRefs.current[fv.id] = ref;
                                        }
                                      }}
                                      initialValue={fv.value}
                                      onChange={newText => {
                                        updateFieldValue(
                                          fv.id,
                                          item.id,
                                          newText,
                                        );
                                      }}
                                      onBlur={() => {
                                        updateCFapi(
                                          item.id,
                                          fv.value,
                                          fv.type,
                                          fv.name,
                                          fv.description,
                                          fv.listValue,
                                        );
                                      }}
                                      editorStyle={{flex: 1}}
                                      containerStyle={{flex: 1}}
                                    />
                                </View>

                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}

                            {fv.type === 'datepicker' && (
                              <View style={styles.rightCtn}>
                                <View style={styles.datePic}>
                                  <TouchableOpacity
                                    onPress={() => setShowDatePicker(fv.id)}
                                    style={{flex: 1, justifyContent: 'center'}}>
                                    {fv.value ? (
                                      <TextCM>
                                        {DateUtils.convertDateToDDMMYYYY(
                                          selectedDate[fv.id] || fv.value,
                                        )}
                                      </TextCM>
                                    ) : (
                                      <TextCM style={{color: '#999'}}>
                                        {t('board.select-date')}
                                      </TextCM>
                                    )}

                                    <DatePickerModal
                                      visible={showDatePicker === fv.id}
                                      onClose={() => setShowDatePicker(null)}
                                      onSelect={(date: string | null) => {
                                        setSelectedDate(prev => ({
                                          ...prev,
                                          [fv.id]: date ? new Date(date) : null,
                                        }));
                                        if (date) {
                                          updateFieldValue(
                                            fv.id,
                                            item.id,
                                            DateUtils.convertDateToDDMMYYYY(
                                              date,
                                            ),
                                          );
                                          updateCFapi(
                                            item.id,
                                            DateUtils.convertToYesterdayISO(
                                              date,
                                            ),
                                            fv.type,
                                            fv.name,
                                            fv.description,
                                            fv.listValue,
                                          );
                                        } else {
                                          updateFieldValue(fv.id, item.id, '');
                                          updateCFapi(
                                            item.id,
                                            '',
                                            fv.type,
                                            fv.name,
                                            fv.description,
                                            fv.listValue,
                                          );
                                        }
                                      }}
                                    />
                                  </TouchableOpacity>
                                </View>
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'select' && (
                              <View style={styles.rightCtn}>
                                <Select
                                  placeholder={t('task.select-value')}
                                  selectedIndex={
                                    selectedIndexes[fv.id] ?? undefined
                                  }
                                  onSelect={index => {
                                    setSelectedIndexes(prev => ({
                                      ...prev,
                                      [fv.id]: index as IndexPath,
                                    }));
                                    const selectedValue =
                                      fv.listValue[(index as IndexPath).row];

                                    updateCFapi(
                                      item.id,
                                      selectedValue,
                                      fv.type,
                                      fv.name,
                                      fv.description,
                                      fv.listValue,
                                    );
                                  }}
                                  value={
                                    selectedIndexes[fv.id]
                                      ? fv.listValue[
                                          (selectedIndexes[fv.id] as IndexPath)
                                            .row
                                        ]
                                      : fv.value
                                  }
                                  style={{flex: 1, marginRight: 8}}>
                                  {fv.listValue.map((item, i) => {
                                    return <SelectItem key={i} title={item} />;
                                  })}
                                </Select>
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'assignee' && (
                              <View style={[styles.rightCtn]}>
                                <View style={{flex: 1}}>
                                  <Popover
                                    visible={showList === fv.id}
                                    anchor={() => (
                                      <View style={{width: 350}}>
                                        {renderAssigneeInput(
                                          fv,
                                          inputRef,
                                          valuesAss,
                                        ) || <View />}
                                      </View>
                                    )}
                                    placement="bottom start"
                                    style={{marginLeft: -40}}
                                    onBackdropPress={() => setShowList(null)}>
                                    <Layout
                                      style={{width: 300, maxHeight: 200}}>
                                      <View style={styles.listPer}>
                                        <List
                                          style={{flexGrow: 0}}
                                          data={listUser}
                                          keyExtractor={ass =>
                                            ass.id.toString()
                                          }
                                          refreshing={refreshing}
                                          onRefresh={onRefresh}
                                          contentContainerStyle={{
                                            backgroundColor: '#fff',
                                            rowGap: 16,
                                          }}
                                          onEndReachedThreshold={0.5}
                                          onEndReached={fetchNextData}
                                          renderItem={({item: ass}) => (
                                            <TouchableOpacity
                                              onPress={() => {
                                                handleSelect(fv.id, ass.email);
                                                Keyboard.dismiss();
                                                setShowList(null);
                                                updateCFapi(
                                                  item.id,
                                                  ass.email,
                                                  fv.type,
                                                  fv.name,
                                                  fv.description,
                                                  fv.listValue,
                                                );
                                              }}>
                                              <View style={styles.assignCtn}>
                                                <Image
                                                  style={styles.imgAss}
                                                  source={{
                                                    uri:
                                                      ass.imageUrl ||
                                                      String.DEFAULT_IMAGE,
                                                  }}
                                                />
                                                <View>
                                                  <TextCM>
                                                    {ass.personalName}
                                                  </TextCM>
                                                  <TextCM>{ass.email}</TextCM>
                                                </View>
                                              </View>
                                            </TouchableOpacity>
                                          )}
                                          scrollEnabled={true}
                                          nestedScrollEnabled={true}
                                          keyboardShouldPersistTaps="handled"
                                        />
                                      </View>
                                    </Layout>
                                  </Popover>
                                </View>

                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}

                            {fv.type === 'email' && (
                              <View style={styles.rightCtn}>
                                <Input
                                  value={fv.value}
                                  onChangeText={newText => {
                                    updateFieldValue(fv.id, item.id, newText);
                                  }}
                                  autoCorrect={false}
                                  onBlur={() => {
                                    const isValidEmail = validEmail.test(
                                      fv.value,
                                    );

                                    if (isValidEmail) {
                                      updateCFapi(
                                        item.id,
                                        fv.value,
                                        fv.type,
                                        fv.name,
                                        fv.description,
                                        fv.listValue,
                                      );
                                    }
                                  }}
                                  style={[
                                    styles.inputBase,
                                    fv.value && !validEmail.test(fv.value)
                                      ? styles.inputError
                                      : styles.inputNormal,
                                  ]}
                                />
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'number' && (
                              <View style={styles.rightCtn}>
                                <Input
                                  value={fv.value}
                                  keyboardType="numeric"
                                  onChangeText={newText => {
                                    const onlyNums = newText.replace(
                                      /[^0-9]/g,
                                      '',
                                    );
                                    updateFieldValue(fv.id, item.id, onlyNums);
                                  }}
                                  onBlur={() => {
                                    updateCFapi(
                                      item.id,
                                      fv.value,
                                      fv.type,
                                      fv.name,
                                      fv.description,
                                      fv.listValue,
                                    );
                                  }}
                                  style={styles.inputCtn}
                                />
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'signature' && (
                              <View style={styles.rightCtn}>
                                <TouchableOpacity
                                  onPress={() => setOpenSignature(item.id)}
                                  style={{flexShrink: 1}}>
                                  {signatureData[item.id] ? (
                                    <Image
                                      source={{
                                        uri: signatureData[item.id] as string,
                                      }}
                                      style={{
                                        width: 250,
                                        height: 80,
                                        resizeMode: 'contain',
                                        flex: 1,
                                      }}
                                    />
                                  ) : item.documents &&
                                    item.documents.length > 0 ? (
                                    item.documents.map(doc => (
                                      <Image
                                        key={doc.id}
                                        source={{
                                          uri: `data:image/png;base64,${
                                            images[doc.id]
                                          }`,
                                        }}
                                        style={styles.imgSign}
                                      />
                                    ))
                                  ) : (
                                    <TextCM style={{color: '#999'}}>
                                      {t('task.enter-sign')}
                                    </TextCM>
                                  )}
                                </TouchableOpacity>

                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                                <ModalSignature
                                  visible={openSignature === item.id}
                                  onClose={() => setOpenSignature(null)}
                                  onSelect={sig => {
                                    setSignatureData(prev => ({
                                      ...prev,
                                      [item.id]: sig,
                                    }));

                                    uploadImage(item.id, fv.id, sig);
                                  }}
                                />
                              </View>
                            )}

                            {fv.type === 'phone' && (
                              <View style={styles.rightCtn}>
                                <Input
                                  value={fv.value}
                                  keyboardType="phone-pad"
                                  onChangeText={newText => {
                                    updateFieldValue(fv.id, item.id, newText);
                                  }}
                                  onBlur={() => {
                                    if (fv.value.length > 7) {
                                      updateCFapi(
                                        item.id,
                                        fv.value,
                                        fv.type,
                                        fv.name,
                                        fv.description,
                                        fv.listValue,
                                      );
                                    }
                                  }}
                                  style={[
                                    styles.inputBase,
                                    fv.value && !checkPhone.test(fv.value)
                                      ? styles.inputError
                                      : styles.inputNormal,
                                  ]}
                                />
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'currency' && (
                              <View style={styles.rightCtn}>
                                <Input
                                  value={fv.value}
                                  keyboardType="numeric"
                                  onChangeText={newText => {
                                    const numericValue = newText.replace(
                                      /\D/g,
                                      '',
                                    );
                                    const formattedValue = numericValue.replace(
                                      /\B(?=(\d{3})+(?!\d))/g,
                                      ',',
                                    );
                                    const finalValue =
                                      formattedValue.length > 0
                                        ? `${fv.currency} ${formattedValue}`
                                        : '';
                                    updateFieldValue(
                                      fv.id,
                                      item.id,
                                      finalValue,
                                    );
                                  }}
                                  onBlur={() => {
                                    updateCFapi(
                                      item.id,
                                      fv.value,
                                      fv.type,
                                      fv.name,
                                      fv.description,
                                      fv.listValue,
                                      fv.currency,
                                    );
                                  }}
                                  style={styles.inputCtn}
                                />
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            {fv.type === 'checkbox' && (
                              <View style={styles.rightCtn}>
                                <View style={styles.checkBoxCtn}>
                                  <CheckBox
                                    checked={checked[fv.id]}
                                    onChange={nextChecked => {
                                      setChecked(prev => ({
                                        ...prev,
                                        [fv.id]: nextChecked,
                                      }));
                                      updateCFapi(
                                        item.id,
                                        nextChecked,
                                        fv.type,
                                        fv.name,
                                        fv.description,
                                        fv.listValue,
                                      );
                                    }}
                                  />
                                </View>
                                <Pressable
                                  onPress={() =>
                                    setConfirmDeleteVisible(item.id)
                                  }>
                                  <DeleteIcon style={styles.icon} />
                                </Pressable>
                              </View>
                            )}
                            <ModalConfirmCM
                              type="cancel"
                              isVisible={confirmDeleteVisible === item.id}
                              onClose={() => setConfirmDeleteVisible(null)}
                              title={t('task.delete-customfield-confirm')}
                              content={t('task.delete-customfield-confirm-1')}
                              onConfirm={() => handleConfirmDelete(item.id)}
                              styleBtnRight={{backgroundColor: Color.RedE14337}}
                              labelCancel="Hủy"
                              labelConfirm="Xác nhận"
                            />
                          </View>
                        </View>
                      );
                    }
                  })}
                </View>
              ))}
            </View>
          ))
        ) : (
          <></>
        )}
      </View>
    </View>
  );
};

export default CustomField;
